const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1) Geometry & Time Definitions
    const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
    const pakistan = countries.filter(ee.Filter.eq('ADM0_NAME', 'Pakistan')).first();
    const geom = ee.Feature(pakistan).geometry();
    const scale = 3000;

    const periods = {
      jan: {start: '2018-01-01', end: '2018-02-01'},
      aug: {start: '2018-08-01', end: '2018-09-01'}
    };

    async function getMonthlyET(period) {
      // Primary dataset
      let src = 'MODIS/006/MOD16A2';
      let col = ee.ImageCollection(src)
        .filterDate(period.start, period.end)
        .filterBounds(geom);
      let n = await col.size().getInfo();

      // Fallback to gap-filled if empty
      if ((n || 0) === 0) {
        src = 'MODIS/006/MOD16A2GF';
        col = ee.ImageCollection(src)
          .filterDate(period.start, period.end)
          .filterBounds(geom);
        n = await col.size().getInfo();
        if ((n || 0) === 0) {
          return {empty: true, images: 0, src: 'None'};
        }
      }

      // Scale factor 0.1 (ET in mm/8day). Sum 8-day composites within month.
      const scaled = col.select('ET').map(function(img) {
        return img.select('ET').multiply(0.1).rename('ET').copyProperties(img, ['system:time_start']);
      });
      const sumImg = ee.ImageCollection(scaled).sum().clip(geom); // approx monthly ET sum

      const countDict = await sumImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const px = countDict ? countDict.ET : null;
      if (px === null || px === 0) {
        return {noValid: true, images: n, src};
      }

      const meanDict = await sumImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const meanVal = meanDict ? meanDict.ET : null;

      if (meanVal === null || !isFinite(meanVal)) {
        return {calcFail: true, images: n, src};
      }

      return {empty: false, noValid: false, calcFail: false, images: n, src, pixels: px, mean: meanVal};
    }

    const jan = await getMonthlyET(periods.jan);
    const aug = await getMonthlyET(periods.aug);

    // Output concise evidence
    console.log(`Jan 2018 Images: ${jan.images || 0} (Source: ${jan.src || 'None'})`);
    console.log(`Aug 2018 Images: ${aug.images || 0} (Source: ${aug.src || 'None'})`);

    // Handle data availability cases
    if (jan.empty || aug.empty) {
      console.log('One or both months have no images after fallback.');
      console.log('C1');
      return;
    }
    if (jan.noValid || aug.noValid) {
      console.log(`Valid Pixels - Jan: ${jan.pixels || 0}, Aug: ${aug.pixels || 0}`);
      console.log('No valid pixels after processing in one or both months.');
      console.log('C2');
      return;
    }
    if (jan.calcFail || aug.calcFail || jan.mean === null || aug.mean === null || !isFinite(jan.mean) || !isFinite(aug.mean)) {
      console.log('Calculation failed (mean is null/NaN).');
      console.log('C3');
      return;
    }

    // Print validation stats and results
    console.log(`Valid Pixels - Jan: ${jan.pixels}, Aug: ${aug.pixels}`);
    console.log(`Jan Mean ET (mm/month approx): ${jan.mean.toFixed(3)}`);
    console.log(`Aug Mean ET (mm/month approx): ${aug.mean.toFixed(3)}`);
    const diff = aug.mean - jan.mean;
    console.log(`Difference (Aug - Jan): ${diff.toFixed(3)} mm`);

    // Final answer: Does ET increase in August 2018 compared to January 2018?
    const answer = diff > 0 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    // Unexpected issues (e.g., asset names, memory, syntax) -> D
    console.log(`Error: ${String(err).slice(0, 200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
